/* Lecture 4 · The Hands: live figures. Every value comes from window.L4 (figdata.js, generated by
   experiments/deck_data.py from experiments/logs/*.json). Loaded BEFORE plates.js; read helpers inside each figure. */
(() => {
const FIGS = (window.FIGS = window.FIGS || {});
const D = () => window.L4;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inr = (n) => '₹' + Number(n).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const num = (n) => Number(n).toLocaleString('en-IN');
/* JSON, pretty-printed and coloured: keys sky, strings ember-brown, numbers and booleans green. */
function hl(obj, indent = 1) {
  const s = typeof obj === 'string' ? obj : JSON.stringify(obj, null, indent);
  return esc(s).replace(/("(?:\\.|[^"\\])*")(\s*:)?|\b(true|false|null)\b|(-?\b\d+(?:\.\d+)?\b)/g, (m, str, colon, kw, n) => {
    if (str) return colon ? `<span class="jk">${str}</span>${colon}` : `<span class="js">${str}</span>`;
    if (kw) return `<span class="jn">${kw}</span>`;
    return `<span class="jn">${n}</span>`;
  });
}
const html = (el, s) => { el.innerHTML = s; return el; };
const btns = (labels, on, cb, cls = '') => `<div class="ctl ${cls}">${labels.map((l, i) => `<button data-i="${i}" class="${i === on ? 'on' : ''}">${l}</button>`).join('')}</div>`;
const wire = (el, cb) => el.querySelectorAll('.ctl button').forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); cb(+b.dataset.i); }));
const cut = (s, n) => (s.length > n ? s.slice(0, n) + '…' : s);

/* ---------------------------------------------------------------- cold open: Ask Rasoi at the knowledge stage */
FIGS.cold = (el) => {
  const t = D().cold;
  const a1 = t[0].answer.split('\n').filter((l) => l.trim())[1].replace(/\*\*/g, '');
  const a2 = t[1].answer.split('\n')[0].replace(/\*\*/g, '');
  html(el, `<div class="thread" style="height:100%;font-size:21px">
    <div class="msg u"><div class="who">Kavita</div>${esc(t[0].user)}</div>
    <div class="msg ag k1"><div class="who">Ask Rasoi · used search_policy</div>${esc(cut(a1, 260))}</div>
    <div class="msg u k2"><div class="who">Kavita</div>${esc(t[1].user)}</div>
    <div class="msg ag k3"><div class="who">Ask Rasoi · used search_policy</div>${esc(a2)} <b>You will need to enter this directly into Bahi.</b></div></div>`);
  return { step(k) { ['k1', 'k2', 'k3'].forEach((c, i) => el.querySelector('.' + c).classList.toggle('hide', k < i + 1)); } };
};

/* ---------------------------------------------------------------- the round trip, scrubbed */
FIGS.rt = (el) => {
  const R = D().roundtrip;
  const r1 = R.rounds[0], r2 = R.rounds[1], r3 = R.rounds[2];
  const names = R.first_tools.map((t) => t.function.name);
  const call = (r) => r.message.tool_calls[0];
  const res = (x) => { const o = JSON.parse(JSON.stringify(x.result)); if (o.items) o.items = o.items.slice(0, 2).concat([`… ${x.result.items.length - 2} more`]); if (o.warehouses) o.warehouses = o.warehouses.map((w) => ({ warehouse: w.warehouse, on_hand: w.on_hand, free: w.free })); return o; };
  const stages = [
    { who: 'Our code → model', h: `POST /chat/completions · request 1 · ${num(r1.request_bytes)} bytes`, j: { model: R.model, messages: [{ role: 'system', content: cut(R.system, 90) }, { role: 'user', content: R.ask }], tools: names.map((n) => `{type: function, function: {name: ${n}, …}}`), temperature: 0 } },
    { who: 'Model → our code', h: `reply 1 · ${r1.seconds} s · ${num(r1.usage.prompt_tokens)} tokens in · finish_reason "${r1.finish}"`, j: r1.message },
    { who: 'Our code → Bahi', h: `we run ${call(r1).function.name} in Kavita's session: Bahi services ${r1.ran[0].services.join(', ')}`, j: res(r1.ran[0]) },
    { who: 'Our code → model', h: `request 2 · ${r2.n_messages} messages · ${num(r2.request_bytes)} bytes: the tool result goes back`, j: { role: 'tool', tool_call_id: r1.ran[0].tool_message.tool_call_id, content: cut(r1.ran[0].tool_message.content, 150) } },
    { who: 'Model → our code', h: `reply 2 · ${r2.seconds} s · ${num(r2.usage.prompt_tokens)} tokens in · another tool call`, j: r2.message },
    { who: 'Our code → Bahi', h: `we run check_stock: Bahi services ${r2.ran[0].services.join(', ')}`, j: res(r2.ran[0]) },
    { who: 'Model → our code', h: `reply 3 · ${r3.seconds} s · ${num(r3.usage.prompt_tokens)} tokens in · finish_reason "${r3.finish}": words`, j: { role: 'assistant', content: r3.message.content } },
  ];
  const say = ['request 1: messages + 15 tools', 'reply 1: a tool call, find_item', 'we run find_item in Bahi', 'request 2: + the tool result', 'reply 2: a tool call, check_stock', 'we run check_stock in Bahi', 'reply 3: the answer, in words'];
  let cur = 0;
  const draw = () => {
    const s = stages[cur];
    html(el, `<div style="display:grid;grid-template-columns:330px 1fr;gap:22px;height:100%">
      <div class="trace" style="font:400 18px/1.35 var(--font);gap:12px">${stages.map((x, i) => `<div class="l" style="opacity:${i <= cur ? 1 : 0.3};${i === cur ? 'color:var(--after);font-weight:600' : ''}"><b>${i + 1}</b> · ${say[i]}<br><span class="tiny">${x.who}</span></div>`).join('')}
        <div class="ctl" style="margin-top:14px"><button data-d="-1">←</button><button data-d="1">→</button></div></div>
      <div><div class="small" style="margin-bottom:8px;color:var(--ink)">${esc(s.h)}</div>
      <pre class="json" style="height:${el.clientHeight - 60}px;font-size:16px;white-space:pre-wrap">${hl(s.j)}</pre></div></div>`);
    el.querySelectorAll('[data-d]').forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); cur = Math.max(0, Math.min(stages.length - 1, cur + +b.dataset.d)); draw(); }));
  };
  return { step(k) { cur = Math.min(k, stages.length - 1); draw(); } };
};

/* ---------------------------------------------------------------- the tool list the model reads */
FIGS.toolpick = (el) => {
  const T = D().roundtrip.first_tools;
  let on = T.findIndex((t) => t.function.name === 'check_stock');
  const draw = () => html(el, `<div style="display:grid;grid-template-columns:300px 1fr;gap:20px;height:100%">
    <div class="ctl" style="flex-direction:column;align-items:stretch;gap:6px;margin:0">${T.map((t, i) => `<button data-i="${i}" class="${i === on ? 'on' : ''}" style="text-align:left;padding:7px 14px">${t.function.name}</button>`).join('')}</div>
    <pre class="json" style="font-size:16.5px;white-space:pre-wrap;height:100%">${hl(T[on])}</pre></div>`) && wire(el, (i) => { on = i; draw(); });
  draw();
  return { step() {} };
};

/* ---------------------------------------------------------------- tool.json, annotated step by step */
FIGS.schema = (el) => {
  const J = D().pr_json;
  const s = J.input_schema;
  const row = (k, v, cls) => `      <span class="${cls}"><span class="jk">"${k}"</span>: {"type": <span class="js">"${v.type}"</span>, "description": <span class="js">"${esc(v.description)}"</span>}</span>\n`;
  html(el, `<pre class="json schemabox" style="font-size:17.5px;line-height:1.6;height:100%;white-space:pre-wrap">{
  <span class="jk">"name"</span>: <span class="js">"${J.name}"</span>,   <span style="font:500 16px var(--font);color:var(--gold)">← the name the model writes</span>
  <span class="jk">"description"</span>: <span class="js a1x">"${esc(cut(J.description, 120))}"</span>
  <span class="jk">"writes"</span>: <span class="jn">${J.writes}</span>,
  <span class="jk">"input_schema"</span>: {
    <span class="jk">"type"</span>: <span class="js">"object"</span>,
    <span class="jk">"properties"</span>: {
${Object.entries(s.properties).map(([k, v]) => row(k, v, k === 'confirm' ? 'a3' : 'a1')).join('')}    },
    <span class="jk a2">"required"</span>: ${hl(s.required, 0)}
  }
}</pre>`);
  return { step(k) {
    el.querySelectorAll('.a1').forEach((x) => x.classList.toggle('hil', k === 1));
    el.querySelectorAll('.a2').forEach((x) => x.classList.toggle('hil', k === 2));
    el.querySelectorAll('.a3').forEach((x) => x.classList.toggle('hil', k === 3));
    el.querySelectorAll('.a1x').forEach((x) => x.classList.toggle('hil', k === 4));
  } };
};

/* ---------------------------------------------------------------- the door: mistakes and what the toolbox says */
FIGS.validator = (el) => {
  const T = D().types;
  const cases = [
    ['quantity: "20000" (text)', 'create_purchase_request', { quantity: '20000' }, { cleaned_to: T.quantity_as_text }],
    ['no need_by', 'create_purchase_request', { need_by: '(missing)' }, T.missing],
    ['decision: "yes"', 'approve_purchase_request', { decision: 'yes' }, T.bad_enum],
    ['item_code: 42', 'check_stock', { item_code: 42 }, T.wrong_type],
    ['extra warehouse: "PUN"', 'check_stock', { warehouse: 'PUN' }, T.unknown_arg],
  ];
  let on = 1;
  const draw = () => {
    const c = cases[on];
    html(el, `${btns(cases.map((x) => x[0]), on)}<div class="small" style="margin:14px 0 6px">${c[1]} with ${esc(JSON.stringify(c[2]))} → the toolbox replies, before any Bahi service runs:</div>
      <pre class="json" style="font-size:17px;white-space:pre-wrap">${hl(c[3])}</pre>`);
    wire(el, (i) => { on = i; draw(); });
  };
  draw();
  return { step() {} };
};

/* ---------------------------------------------------------------- what one tool does behind its name */
FIGS.services = (el) => {
  const S = D().check_stock_services, R = D().check_stock;
  html(el, `<div style="display:flex;flex-direction:column;gap:12px">
    <div class="card af" style="font-size:21px"><b>check_stock</b>(item_code = "GSK-SIL-05L") · one tool call from the model</div>
    ${S.map((s, i) => `<div class="lyr leg sv sv${i}" style="font-size:19px"><span><code>${s.svc}</code> ${esc(JSON.stringify(s.payload))}</span><span class="tg">Bahi service ${i + 1} · rc ${s.rc}</span></div>`).join('')}
    <div class="card sv sv4" style="font-size:19px">Added up by tool.py: Pune ${num(R.warehouses[0].free)} + Chakan ${num(R.warehouses[1].free)} = <b>${num(R.free_total)} free</b> · reorder level ${num(R.reorder_level)} · <b>${R.cover_days} days</b> of cover</div></div>`);
  const at = [1, 1, 2, 2, 3];
  return { step(k) { for (let i = 0; i < 5; i++) el.querySelector('.sv' + i).classList.toggle('fade', k < at[i]); } };
};

/* ---------------------------------------------------------------- tokens the definitions cost */
FIGS.tokbars = (el) => {
  const T = D().tokens;
  const per = Object.entries(T.per_tool).sort((a, b) => b[1] - a[1]);
  const mx = T.raw.tokens;
  html(el, `<div class="cmp" style="gap:16px">
    <div class="row"><div class="lab">41 raw services</div><div class="br"><div class="bar b tb0" style="width:0">${num(T.raw.tokens)} tokens · ${num(T.raw.chars)} chars</div></div></div>
    <div class="row"><div class="lab">15 toolbox tools</div><div class="br"><div class="bar a tb1" style="width:0">${num(T.toolbox.tokens)} tokens · ${num(T.toolbox.chars)} chars</div></div></div>
    <div class="row"><div class="lab">same 15 over MCP</div><div class="br"><div class="bar a tb2" style="width:0">${num(T.mcp.tokens)} tokens</div></div></div></div>
    <div class="per" style="margin-top:26px;display:grid;grid-template-columns:1fr 1fr;gap:6px 26px;font-size:17px">${per.map(([n, v]) => `<div style="display:grid;grid-template-columns:250px 1fr;align-items:center;gap:8px"><code>${n}</code><div style="height:16px;width:${v / 3.2}px;background:var(--after-2);border-radius:5px;position:relative"><span style="position:absolute;left:${v / 3.2 + 6}px;top:-3px;font:500 15px var(--font);color:var(--after)">${v}</span></div></div>`).join('')}</div>`);
  return { step(k) {
    [T.raw.tokens, T.toolbox.tokens, T.mcp.tokens].forEach((v, i) => { el.querySelector('.tb' + i).style.width = k >= Math.min(i, 1) ? (v / mx) * 690 + 'px' : '0'; });
    el.querySelector('.per').style.opacity = k >= 2 ? 1 : 0;
  } };
};

/* ---------------------------------------------------------------- the experiment: raw vs toolbox */
FIGS.results = (el) => {
  const E = D().exp;
  let m = 'flash';
  const metrics = [['Tasks passed (of 30)', 'passed', (v) => v + ' / 30'], ['Tokens per task', 'tokens_mean', num], ['Tool calls per task', 'tool_calls_mean', (v) => v],
    ['Bahi refusals (all 30)', 'bahi_refusals_total', (v) => v], ['₹ per task', 'inr_mean', (v) => inr(v)], ['Never-events', 'never_events', (v) => v]];
  let shown = 0;
  const draw = () => {
    const C = E[m].configs;
    html(el, `${btns(['gemini-3.8-flash', 'gemini-3.5-flash-lite'], m === 'flash' ? 0 : 1)}
      <div class="cmp" style="margin-top:18px;gap:14px">${metrics.map(([lab, key, f], i) => {
        const a = C.raw[key], b = C.toolbox[key], mx = Math.max(a, b) || 1;
        return `<div class="row" style="opacity:${i < shown ? 1 : 0.12}"><div class="lab">${lab}</div><div class="br">
          <div class="bar b ${a ? '' : 'zero'}" style="width:${a ? Math.max(4, (a / mx) * 760) : 200}px">raw ${f(a)}</div>
          <div class="bar a ${b ? '' : 'zero'}" style="width:${b ? Math.max(4, (b / mx) * 760) : 200}px">toolbox ${f(b)}</div></div></div>`;
      }).join('')}</div>`);
    wire(el, (i) => { m = i ? 'lite' : 'flash'; draw(); });
  };
  return { step(k) { shown = [2, 4, 6][Math.min(k, 2)]; draw(); } };
};

/* ---------------------------------------------------------------- 30 tasks x 2 tool sets */
const plain = (n) => n.replace(/\\b/g, '').replace(/\(\?:/g, '(').replace(/,\?/g, ',').replace(/\?/g, '').replace(/\\./g, '.').replace(/^missing /, 'the answer did not mention ').replace(/did not say /, 'did not mention ').replace(/ \| /g, ' / ').replace(/certific\S*.*$/, 'the certificate (or onboarding)').replace(/PRD-07 \/ PRD-03 \/ MNT-01 \/ ADM-01/, 'the open cost centres');
FIGS.grid = (el) => {
  const E = D().exp;
  let m = 'flash', sel = null;
  const draw = () => {
    const G = E[m].grid;
    const cell = (r, c) => `<span class="chip ${r[c].pass ? 'p' : 'f'}" data-t="${r.id}" style="cursor:pointer;min-width:0;width:100%;text-align:center">${r[c].pass ? 'pass' : 'fail'}</span>`;
    const s = G.find((r) => r.id === sel);
    html(el, `${btns(['gemini-3.8-flash', 'gemini-3.5-flash-lite'], m === 'flash' ? 0 : 1)}
      <div style="display:grid;grid-template-columns:repeat(15,1fr);gap:6px 6px;margin-top:14px;font:500 15px var(--font)">
      ${[0, 15].map((o) => G.slice(o, o + 15).map((r) => `<div style="text-align:center;color:var(--ink-2)">${r.id}</div>`).join('') + G.slice(o, o + 15).map((r) => cell(r, 'raw')).join('') + G.slice(o, o + 15).map((r) => cell(r, 'toolbox')).join('')).join('<div style="grid-column:1/-1;height:14px"></div>')}
      </div><div class="small" style="margin-top:6px">In each block: top row raw services, bottom row toolbox. Click a cell.</div>
      <div class="card" style="margin-top:12px;font-size:19px;min-height:150px">${s ? `<b>${s.id}</b> · ${esc(s.ask)}<br><span class="tiny">trap: ${esc(s.trap)}</span><br><span class="b">raw</span> ${s.raw.pass ? 'pass' : 'fail: ' + esc(plain(s.raw.note))} · ${s.raw.calls} tool calls · ${num(s.raw.tokens)} tokens<br><span class="a">toolbox</span> ${s.toolbox.pass ? 'pass' : 'fail: ' + esc(plain(s.toolbox.note))} · ${s.toolbox.calls} tool calls · ${num(s.toolbox.tokens)} tokens` : 'Pick a task to see what was asked, the trap, and what each agent did.'}</div>`);
    wire(el, (i) => { m = i ? 'lite' : 'flash'; draw(); });
    el.querySelectorAll('[data-t]').forEach((c) => c.addEventListener('click', (e) => { e.stopPropagation(); sel = c.dataset.t; draw(); }));
  };
  sel = 'L02';
  draw();
  return { step() {} };
};

/* ---------------------------------------------------------------- errors: Bahi's words vs the toolbox's */
FIGS.errcmp = (el) => {
  const E = D().errors, T = D().types_raw;
  const cases = [['Release an order Rohit has not signed', E.release_unapproved_raw, E.release_unapproved],
    ['A mistyped item code', E.item_typo_raw, E.item_typo],
    ['Quantity in words', T.pr_save_qty_text, D().types.missing]];
  let on = 0;
  const draw = () => {
    const c = cases[on];
    html(el, `${btns(cases.map((x) => x[0]), on)}<div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:16px">
      <div><span class="tag bf">Bahi's raw service says</span><pre class="json" style="font-size:17px;white-space:pre-wrap;background:var(--before-soft)">${hl(c[1])}</pre></div>
      <div><span class="tag af">The toolbox says</span><pre class="json" style="font-size:17px;white-space:pre-wrap;background:var(--after-soft)">${hl(c[2])}</pre></div></div>
      ${on === 2 ? '<p class="small" style="margin-top:8px">(For words in a number field the toolbox stops it at the door; shown: its reply when a required field is missing.)</p>' : ''}`);
    wire(el, (i) => { on = i; draw(); });
  };
  draw();
  return { step() {} };
};

/* ---------------------------------------------------------------- preview, confirm, approve */
FIGS.preview = (el) => {
  const P = D().preview, C = D().confirm, A = D().rohit_approves;
  const pv = P.result.preview;
  html(el, `<div style="display:flex;flex-direction:column;gap:8px">
    <div class="p0"><span class="tag nt">confirm=false · preview · pr rows in Bahi before ${P.pr_rows_before}, after ${P.pr_rows_after}</span>
      <pre class="json" style="font-size:15.5px;padding:10px 16px">${hl({ estimated_rate: pv.estimated_rate, estimated_value: pv.estimated_value, needs_approval: pv.needs_approval, your_limit: pv.your_limit, approver: pv.approver, cost_centre_state: pv.cost_centre_state, note: P.result.note })}</pre></div>
    <div class="p1"><span class="tag af">Kavita says yes · confirm=true · receipt read back from Bahi</span>
      <pre class="json" style="font-size:15.5px;white-space:pre-wrap;padding:10px 16px">${hl({ request_no: C.request_no, status: C.status, approver: C.approver, next_step: C.next_step })}</pre></div>
    <div class="p2"><span class="tag af">Rohit, in his own session</span>
      <pre class="json" style="font-size:15.5px;padding:10px 16px">${hl({ request_no: A.request_no, status: A.status, decided_by: A.decided_by }, 0)}</pre></div></div>`);
  return { step(k) { [0, 1, 2].forEach((i) => el.querySelector('.p' + i).classList.toggle('fade', k < i)); } };
};

/* ---------------------------------------------------------------- idempotency under a lost reply */
FIGS.idem = (el) => {
  const R = D().idem_direct_raw, T = D().idem_direct;
  const rawA = R.attempts.map((a) => (typeof a.reply === 'string' ? 'TIMEOUT: no reply within 30 s' : `${a.reply.rc} · ${a.reply.msg}`));
  html(el, `<div style="display:grid;grid-template-columns:1fr 1fr;gap:22px">
    <div class="card bf"><span class="tag bf">Raw po_save, retried</span>
      <div class="i1 lyr" style="margin:8px 0;font-size:18px;background:#fff">try 1 → Bahi saves → reply lost<br><code>${esc(rawA[0])}</code></div>
      <div class="i2 lyr" style="margin:8px 0;font-size:18px;background:#fff">try 2 → <code>${esc(rawA[1])}</code></div>
      <div class="i3" style="font-size:20px;margin-top:10px"><b>${R.orders.length} orders</b> in Bahi: ${R.orders.map((o) => `${o.po_no} ${inr(o.gross_value)}`).join(' · ')}</div></div>
    <div class="card af"><span class="tag af">create_purchase_order, retried</span>
      <div class="i1 lyr" style="margin:8px 0;font-size:18px;background:#fff">try 1 → Bahi saves → reply lost → the tool looks the order up by its key → <code>${T.first.po_no} ${esc(T.first.status)}</code></div>
      <div class="i2 lyr" style="margin:8px 0;font-size:18px;background:#fff">try 2 → <code>already_done: ${T.retry.already_done}</code> · ${esc(T.retry.note)}</div>
      <div class="i3" style="font-size:20px;margin-top:10px"><b>${T.orders.length} order</b> in Bahi: ${T.orders.map((o) => `${o.po_no} · key ${o.client_ref}`).join(' · ')}</div></div></div>`);
  return { step(k) { [1, 2, 3].forEach((i) => el.querySelectorAll('.i' + i).forEach((x) => x.classList.toggle('fade', k < i))); } };
};

/* ---------------------------------------------------------------- the silent Draft: SAVED vs the receipt */
FIGS.draft = (el) => {
  const R = D().draft_raw, T = D().draft_receipt;
  html(el, `<div style="display:grid;grid-template-columns:1fr 1.25fr;gap:22px">
    <div><span class="tag bf">Bahi's po_save reply</span><pre class="json" style="font-size:18px;background:var(--before-soft)">${hl(R)}</pre>
      <p class="small">rc "S" means success. The message says SAVED. The status code DR is easy to miss.</p></div>
    <div class="d1"><span class="tag af">The toolbox's receipt, read back with po_get</span><pre class="json" style="font-size:17px;white-space:pre-wrap;background:var(--after-soft)">${hl({ po_no: T.po_no, status: T.status, cost_centre: T.cost_centre, sent_to_supplier: T.sent_to_supplier, warning: T.warning })}</pre></div></div>`);
  return { step(k) { el.querySelector('.d1').classList.toggle('fade', k < 1); } };
};

/* ---------------------------------------------------------------- JSON-RPC: three kinds of message */
FIGS.jsonrpc = (el) => {
  const W = D().wire.stdio;
  const req = W.find((w) => w.msg.method === 'initialize').msg, resp = W[1].msg, note = W.find((w) => w.msg.method === 'notifications/initialized').msg;
  html(el, `<div style="display:flex;flex-direction:column;gap:12px">
    <div class="q0"><span class="tag af">a request: has an id, a method, params</span><pre class="json" style="font-size:16.5px;white-space:pre-wrap">${hl(req, 0)}</pre></div>
    <div class="q1"><span class="tag af">its response: the same id, and a result (or an error)</span><pre class="json" style="font-size:16.5px;white-space:pre-wrap">${hl(resp, 0)}</pre></div>
    <div class="q2"><span class="tag nt">a notification: no id, so no reply</span><pre class="json" style="font-size:16.5px">${hl(note, 0)}</pre></div></div>`);
  return { step(k) { [0, 1, 2].forEach((i) => el.querySelector('.q' + i).classList.toggle('fade', k < i)); } };
};

/* ---------------------------------------------------------------- the stdio session, line by line */
FIGS.wire = (el) => {
  const W = D().wire.stdio;
  let cur = 3;
  const draw = () => {
    const w = W[cur];
    html(el, `<div style="display:grid;grid-template-columns:400px 1fr;gap:20px;height:100%">
      <div class="trace" style="font-size:16.5px;gap:8px">${W.map((x, i) => `<div class="l" data-w="${i}" style="cursor:pointer;opacity:${i === cur ? 1 : 0.55};${i === cur ? 'color:var(--after);font-weight:600' : ''}">${x.dir === '->' ? 'client →' : '← server'} ${x.msg.method || (x.msg.result ? 'result' : 'error')}${x.msg.params && x.msg.params.name ? ' ' + x.msg.params.name : ''} · ${num(x.bytes)} B</div>`).join('')}</div>
      <pre class="json" style="font-size:15.5px;white-space:pre-wrap;height:100%">${hl(w.msg)}</pre></div>`);
    el.querySelectorAll('[data-w]').forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); cur = +b.dataset.w; draw(); }));
  };
  const order = [3, 4, 5, 6];
  return { step(k) { cur = order[Math.min(k, order.length - 1)]; draw(); } };
};

/* ---------------------------------------------------------------- streamable HTTP, the same messages */
FIGS.http = (el) => {
  const H = D().wire.http;
  html(el, `<table class="t" style="font-size:18px"><thead><tr><th>POST /mcp body</th><th>headers we sent</th><th>status</th><th>reply type</th></tr></thead><tbody>
    ${H.map((h) => `<tr><td class="n">${h.method}</td><td class="n" style="font-size:15px">${h.request_headers['mcp-session-id'] ? 'mcp-session-id: ' + h.request_headers['mcp-session-id'].slice(0, 10) + '…<br>mcp-protocol-version: ' + h.request_headers['mcp-protocol-version'] : 'Accept: application/json, text/event-stream'}</td><td class="n">${h.status}</td><td class="n">${h.content_type}</td></tr>`).join('')}</tbody></table>
    <div class="small" style="margin-top:14px">The first reply, as raw text off the socket (a server-sent event):</div>
    <pre class="json" style="font-size:15.5px;white-space:pre-wrap">${esc(H[0].raw.replace(/\r/g, ''))}</pre>`);
  return { step() {} };
};

/* ---------------------------------------------------------------- Ask Rasoi at the hands stage: the recorded conversation */
FIGS.chat = (el) => {
  const T = D().demo.turns, P = D().demo.pr;
  const short = (s) => s.split('\n').filter((l) => l.trim()).slice(0, 3).join(' ').replace(/\*\*/g, '').replace(/`/g, '').replace(/\* /g, '· ');
  const args = (a) => Object.entries(a).sort((x, y) => (y[0] === 'confirm') - (x[0] === 'confirm')).map(([k, v]) => `${k}=${v}`).join(', ');
  const card = (c) => `<div class="pv" style="font-size:14.5px;padding:5px 10px;margin-top:5px">${c.tool}(${esc(cut(args(c.args), 44))})</div>`;
  const bub = (t, i) => `<div class="msg u t${i}" style="padding:5px 12px;font-size:17px"><div class="who">${t.who}</div>${esc(t.user)}</div>
      <div class="msg ag t${i}" style="padding:5px 12px;font-size:17px;max-width:94%"><div class="who">Ask Rasoi · ${num(t.tokens_in)} tokens in · ${t.seconds} s</div>${esc(cut(short(t.answer), 112))}${t.calls.map(card).join('')}</div>`;
  const win = (who, idx) => `<div class="thread" style="gap:6px;padding:12px 14px"><div class="h" style="font:600 13px/1 var(--font);letter-spacing:.06em;text-transform:uppercase;color:var(--after)">${who}</div>${idx.map((i) => bub(T[i], i)).join('')}</div>`;
  html(el, `<div style="display:grid;grid-template-columns:1.12fr 1fr;gap:20px;height:100%">${win("Kavita's Ask Rasoi · server bound to KJOSHI", [0, 1, 2])}
    <div style="display:flex;flex-direction:column;gap:14px">${win("Rohit's Ask Rasoi · server bound to RMEHTA", [3, 4])}
    <div class="card af t5" style="font-size:18px"><b>Read back from Bahi</b>: ${P.pr_no} · status ${P.status} · raised by ${P.raised_by} · approved by ${P.approved_by} · ${inr(P.est_value)}</div></div></div>`);
  return { step(k) { for (let i = 0; i < 6; i++) el.querySelectorAll('.t' + i).forEach((x) => x.classList.toggle('hide', k < i)); } };
};

/* ---------------------------------------------------------------- the map, with the Hands lit */
FIGS.map = (el) => {
  /* band positions are fractions of the master figure (figures/ask_rasoi_architecture_wide.png, 2752 x 1536) */
  const dim = (t, h, l = 0, w = 0.875) => `<div class="dim" style="position:absolute;left:${l * 100}%;top:${t * 100}%;width:${w * 100}%;height:${h * 100}%"></div>`;
  html(el, `<div style="position:relative;width:100%;aspect-ratio:2752/1536">
    <img src="figs/arch_wide.jpg" alt="The Ask Rasoi architecture" style="width:100%;height:100%;border-radius:18px">
    ${dim(0.015, 0.2)}${dim(0.235, 0.255)}${dim(0.805, 0.18)}${dim(0.015, 0.97, 0.9, 0.08)}
    <div class="lit" style="position:absolute;left:2.4%;top:50.5%;width:84.8%;height:27.6%;border:4px solid var(--after);border-radius:18px;box-shadow:0 0 0 9999px rgba(255,255,255,0)"></div></div>`);
  return { step(k) { el.querySelectorAll('.dim').forEach((d) => (d.style.opacity = k >= 1 ? 1 : 0)); el.querySelector('.lit').style.opacity = k >= 1 ? 1 : 0; } };
};
})();
